data.query:
query Query($where: ProductWhereInput, $orderBy: [ProductOrderByInput!], $first: Int, $after: String) {
  product(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    total
    edges {
      node {
        id
        code
        active
        externalId
        productType {
          id
          name
          assembly
          charge
          component
          service
          subAssembly
          usable
          description
          externalId
        }
      }
    }
  }
  facility (where:{active:{_eq:true}}) {
    edges {
      node {
        id
        code
        externalId
      }
    }
  }
}

data.variablesTransform:
{
	"payload": $state.context.REMOTE.item.{
		"update": {
			"externalId": $string(id),
			"code": itemid,
