			"number": $string(itemid),
			"active": isinactive = "F",
			"productTypeId": itemtype,
			"productStageId": isinactive = "F" ? "Active" : "Inactive",
			"integrationData": $
		},
		"where": { "id": $$.product.edges.node.id }
	}
}

{
	"payload": $state.context.REMOTE.item.{
		"create": {
			"externalId": $string(id),
			"code": itemid,
			"name": $coalesce([displayname, itemid]),
			"number": $string(itemid),
			"version": "0",
			"active": isinactive = "F",
			"productTypeId": itemtype,
			"productStageId": isinactive = "F" ? "Active" : "Inactive",
			"integrationData": $
		}
	}
}

{
  "where": {
    "productId": {
      "_in": [$.*.id]
    }/* ,
    "active":{"_eq":true} */
  }
}

data.query:
query Query($where: ProductStrategyWhereInput, $orderBy: [ProductStrategyOrderByInput!], $first: Int, $after: String) {
  productStrategy(where: $where, orderBy: $orderBy, first: $first, after: $after) {
  total  
  edges {
      node {
        id
        code
        active
        primary
        validated
        externalId
        revision
        facility{
      id
      externalId
    }
      }
    }
  }
}

